function result = f90_xcomm09_extract_reference_evidence(modelPath, outputDir, evaluationMode)
% Extract fixed multi-scenario evidence. Scoring is deliberately offline.

repo = localProjectRoot();
if nargin < 3, evaluationMode = "reference"; end
taskDir = string(getenv("SIMUVERITY_TASK_ROOT"));
sourceDir = fullfile(taskDir, "reference", "source");
if strcmpi(string(evaluationMode), "reference")
    sourceDir = string(getenv("SIMUVERITY_EVALUATOR_ASSET_ROOT"));
    assert(isfolder(sourceDir), "SimuVerity:F90:XCOMM09:ReferenceAssetRoot", ...
        "Evaluator-owned reference asset root is missing.");
end
if nargin < 1 || strlength(string(modelPath)) == 0
    modelPath = fullfile(sourceDir, ...
        "HTLinkModelWLANModel.slx");
end
generationRunId = string(getenv("SIMUVERITY_GENERATION_RUN_ID"));
if strlength(generationRunId) == 0
    generationRunId = "f90_xcomm09_manual_" + string(datetime("now", ...
        "Format", "yyyyMMdd'T'HHmmss"));
end
if nargin < 2 || strlength(string(outputDir)) == 0
    outputDir = fullfile(repo, "results", "cross_domain", ...
        "simuverity_public", "F90-XCOMM-09", "fixed_evidence", generationRunId);
end
if ~isfolder(outputDir), mkdir(outputDir); end

official = jsondecode(fileread(simuverity_official_scenarios_path()));
if strcmpi(string(evaluationMode), "candidate")
    result = localRunCandidate(modelPath, outputDir, official, generationRunId);
    return;
end
bindings = struct( ...
    "model", "present", ...
    "params", "present", ...
    "noise", "present");
paramsPath = fullfile(sourceDir, "HTLinkModelWLANExample_params.m");
noisePath = fullfile(sourceDir, "htNoiseEstimate.m");
bindingBefore = struct( ...
    "model", localFilePresence(modelPath), ...
    "params", localFilePresence(paramsPath), ...
    "noise", localFilePresence(noisePath));
isReference = lower(strtrim(string(getenv("SIMUVERITY_EVALUATION_SUBJECT")))) == "reference";

[modelDir, modelName] = fileparts(modelPath);
addpath(modelDir, "-begin");
cleanupPath = onCleanup(@() rmpath(modelDir)); %#ok<NASGU>
localConfigureFileGeneration();

evidence = struct( ...
    "schema", "simuverity.f90-xcomm09-evidence.v1", ...
    "task_id", "F90-XCOMM-09", ...
    "generation_run_id", generationRunId, ...
    "model_path", string(modelPath), ...
    "source_file_presence_before", bindingBefore, ...
    "reference_direct_golden", isReference, ...
    "reference_substantive_modifications", 0, ...
    "reference_runtime_changes", ...
        "non-invasive logging taps and official input settings only", ...
    "extraction_only", true, ...
    "contains_score_decisions", false, ...
    "load_pass", false, ...
    "update_pass", false, ...
    "compile_pass", false, ...
    "nominal_smoke_pass", false, ...
    "static_audit", struct(), ...
    "profile", struct(), ...
    "scenarios", [], ...
    "errors", {{}}, ...
    "started_at", localNow());

try
    assert(isReference, "SimuVerity:F90:XCOMM09:ReferenceIdentity", ...
        "Pinned model or helper file presence does not match.");
    load_system(modelPath);
    evidence.load_pass = true;
    set_param(modelName, "SimulationMode", "normal");
    localInstallReferenceTaps(modelName);
    localSuppressVisualizationSinks(modelName);
    evidence.static_audit = localStaticAudit(modelName);
    evidence.profile = localCompactProfile(modelName);

    nominal = official.scenarios(1);
    localApplyScenario(modelName, nominal);
    set_param(modelName, "SimulationCommand", "update");
    evidence.update_pass = true;
    feval(modelName, [], [], [], "compile");
    feval(modelName, [], [], [], "term");
    evidence.compile_pass = true;

    localClearOutputs();
    sim(modelName, "ReturnWorkspaceOutputs", "on", ...
        "StopTime", "1", "SimulationMode", "normal");
    evidence.nominal_smoke_pass = true;

    rows = repmat(localEmptyScenario(), numel(official.scenarios), 1);
    for index = 1:numel(official.scenarios)
        scenario = official.scenarios(index);
        row = localEmptyScenario();
        row.id = string(scenario.id);
        row.requested_inputs = rmfield(scenario, "id");
        started = tic;
        try
            localClearOutputs();
            localApplyScenario(modelName, scenario);
            out = sim(modelName, "ReturnWorkspaceOutputs", "on", ...
                "StopTime", string(double(scenario.packet_transactions) - 1), ...
                "SimulationMode", "normal");
            signals = localReadOutputs(out);
            row.output_contract = localOutputContract(signals);
            row.metrics = localMetrics(signals, scenario);
            row.simulation_pass = true;
            row.valid = all(structfun(@(value) logical(value), ...
                row.output_contract));
            if ~row.valid
                row.error = struct( ...
                    "identifier", "SimuVerity:F90:XCOMM09:OutputContract", ...
                    "message", ...
                    "One or more required evidence contracts failed.");
            end
        catch exception
            row.error = localError(exception);
        end
        row.wall_seconds = toc(started);
        rows(index) = row;
    end
    evidence.scenarios = rows;
catch exception
    evidence.errors{end + 1} = localError(exception);
    try
        feval(modelName, [], [], [], "term");
    catch
    end
end

try
    close_system(modelName, 0);
catch
end
bindingAfter = struct( ...
    "model", localFilePresence(modelPath), ...
    "params", localFilePresence(paramsPath), ...
    "noise", localFilePresence(noisePath));
evidence.source_file_presence_after = bindingAfter;
evidence.reference_binding_preserved = ...
    bindingAfter.model == bindings.model && ...
    bindingAfter.params == bindings.params && bindingAfter.noise == bindings.noise;
evidence.model_closed_without_save = true;
evidence.finished_at = localNow();
evidence.runtime = struct( ...
    "matlab_release", string(version("-release")), ...
    "generation_run_id", generationRunId, ...
    "matlab_prefdir", string(prefdir), ...
    "appdata", string(getenv("APPDATA")), ...
    "temp", string(getenv("TEMP")), ...
    "cache", string(getenv("SIMULINK_CACHE_FOLDER")), ...
    "codegen", string(getenv("SIMULINK_CODEGEN_FOLDER")), ...
    "mcp_port", string(getenv("SIMUVERITY_MCP_PORT")));

evidencePath = fullfile(outputDir, "evidence.json");
localWriteJson(evidencePath, evidence);
result = evidence;
validCount = 0;
if ~isempty(evidence.scenarios)
    validCount = sum([evidence.scenarios.valid]);
end
fprintf("F90_XCOMM09_EVIDENCE load=%d update=%d compile=%d smoke=%d valid=%d/%d path=%s\n", ...
    evidence.load_pass, evidence.update_pass, evidence.compile_pass, ...
    evidence.nominal_smoke_pass, validCount, numel(evidence.scenarios), ...
    evidencePath);
end

function evidence=localRunCandidate(modelPath,outputDir,official,generationRunId)
[modelDir,model]=fileparts(modelPath);model=string(model);
evidence=struct("schema","simuverity.f90-xcomm09-evidence.v1", ...
 "task_id","F90-XCOMM-09","generation_run_id",generationRunId,"reference_direct_golden",false, ...
 "evaluation_subject","candidate","reference_binding_preserved",false, ...
 "extraction_only",true,"contains_score_decisions",false, ...
 "load_pass",false,"update_pass",false,"compile_pass",false, ...
 "nominal_smoke_pass",false,"static_audit",struct,"scenarios",struct([]),"errors",{{}});
try
 addpath(modelDir,"-begin");load_system(modelPath);evidence.load_pass=true;
 set_param(model,"SimulationMode","normal");
 localApplyCandidateScenario(official.scenarios(1));
 set_param(model,"SimulationCommand","update");evidence.update_pass=true;
 feval(model,[],[],[],"compile");feval(model,[],[],[],"term");evidence.compile_pass=true;
 evidence.static_audit=localCandidateStaticAudit(model);
 sim(model,"ReturnWorkspaceOutputs","on","StopTime","1");evidence.nominal_smoke_pass=true;
 rows=repmat(localEmptyScenario(),numel(official.scenarios),1);
 for index=1:numel(official.scenarios)
  scenario=official.scenarios(index);row=localEmptyScenario();row.id=string(scenario.id);
  row.requested_inputs=rmfield(scenario,"id");
  try
   localApplyCandidateScenario(scenario);
   out=sim(model,"ReturnWorkspaceOutputs","on", ...
    "StopTime",string(double(scenario.packet_transactions)-1));
   [signals,contract]=localReadCandidateOutputs(out);
   row.output_contract=contract;row.metrics=localCandidateMetrics(signals,scenario);
   row.simulation_pass=true;row.valid=all(structfun(@logical,contract));
  catch exception,row.error=localError(exception);end
  rows(index)=row;
 end
 evidence.scenarios=rows;
catch exception,evidence.errors{end+1}=localError(exception);end
try,close_system(model,0);catch,end
evidence.model_closed_without_save=true;evidence.finished_at=localNow();
localWriteJson(fullfile(outputDir,"evidence.json"),evidence);
end

function localApplyCandidateScenario(scenario)
for name=["mcs_index","snr_db","payload_seed","channel_seed","noise_seed"]
 assignin("base",name,double(scenario.(name)));
end
assignin("base","spatial_mapping",string(scenario.spatial_mapping));
end

function [signals,contract]=localReadCandidateOutputs(out)
packet=simuverity_public_output_compatibility(out,"packet_state",[],AllowBaseWorkspace=true);
sync=simuverity_public_output_compatibility(out,"synchronization_state",[],AllowBaseWorkspace=true);
mimo=simuverity_public_output_compatibility(out,"mimo_state",[],AllowBaseWorkspace=true);
quality=simuverity_public_output_compatibility(out,"quality_state",[],AllowBaseWorkspace=true);
[~,p,~]=localFrameMatrix(packet);[~,s,~]=localFrameMatrix(sync);
[~,m,~]=localFrameMatrix(mimo);[~,q,~]=localFrameMatrix(quality);
assert(size(p,2)>=16385&&size(s,2)>=4&&size(m,2)>=7&&size(q,2)>=3, ...
 "SimuVerity:F90:XCOMM09:CandidatePublicLayout", ...
 "packet/synchronization/mimo/quality layouts must expose 16385/4/7/3 numeric columns.");
signals=struct("tx",p(:,1:8192),"rx",p(:,8193:16384),"detected",p(:,16385), ...
 "sync",s(:,1:4),"channel",m(:,1:4),"equalized",m(:,5:6), ...
 "noise",real(m(:,7)),"quality",real(q(:,1:3)));
contract=struct("packet_state_complete",all(isfinite(p),"all"), ...
 "synchronization_complete",all(isfinite(s),"all"), ...
 "mimo_state_complete",all(isfinite(real(m)),"all")&&all(isfinite(imag(m)),"all"), ...
 "quality_state_complete",all(isfinite(q),"all"), ...
 "noise_estimate_positive",all(signals.noise>0));
end

function metrics=localCandidateMetrics(x,scenario)
tx=round(real(x.tx));rx=round(real(x.rx));packetError=any(tx~=rx,2);
reported=x.quality(end,:);channel=x.channel;eq=x.equalized;noise=x.noise;
if size(channel,1)>1,change=mean(abs(diff(channel,1,1)),"all")/max(mean(abs(channel),"all"),eps);else,change=0;end
 streamMetrics=localStreamMetrics(struct("matrix",eq,"sample_shape",[1 2]), ...
     localModulationOrder(double(scenario.mcs_index)));
 channelMetrics=localChannelMetrics(struct( ...
     "matrix",channel,"sample_shape",[1 2 2]));
 requestedPackets=double(scenario.packet_transactions);
 completedPackets=min([reported(3),size(tx,1),size(rx,1)]);
 metrics=struct("reported_per",reported(1),"reported_packet_errors",reported(2), ...
 "reported_compared_packets",reported(3),"reported_per_consistency_error", ...
 abs(reported(1)-reported(2)/max(reported(3),1)),"manual_per",mean(packetError), ...
 "manual_packet_errors",sum(packetError),"manual_compared_packets",size(tx,1), ...
 "reported_manual_per_difference",abs(reported(1)-mean(packetError)), ...
 "packet_detection_fraction",mean(x.detected>0.5),"detected_packet_count",sum(x.detected>0.5), ...
 "coarse_packet_offset_median_samples",median(x.sync(:,1)), ...
 "coarse_packet_offset_span_samples",max(x.sync(:,1))-min(x.sync(:,1)), ...
 "coarse_cfo_median_hz",median(x.sync(:,2)),"coarse_cfo_rms_hz",rms(x.sync(:,2)), ...
 "fine_cfo_median_hz",median(x.sync(:,3)),"fine_cfo_rms_hz",rms(x.sync(:,3)), ...
 "symbol_timing_offset_median_samples",median(x.sync(:,4)), ...
 "symbol_timing_offset_span_samples",max(x.sync(:,4))-min(x.sync(:,4)), ...
 "noise_estimate_mean",mean(noise),"noise_estimate_median",median(noise), ...
 "measured_channel_output_snr_db",10*log10(mean(abs(eq).^2,"all")/max(mean(noise),eps)), ...
 "channel_normalized_difference",change,"channel_exact_copy_fraction",mean(abs(diff(channel,1,1))<1e-12,"all"), ...
 "equalized_stream_count",streamMetrics.count,"stream1_evm",streamMetrics.evm1, ...
 "stream2_evm",streamMetrics.evm2,"worst_stream_evm",max(streamMetrics.evm1,streamMetrics.evm2), ...
 "stream_evm_imbalance",abs(streamMetrics.evm1-streamMetrics.evm2), ...
 "equalized_stream_correlation",streamMetrics.correlation, ...
 "channel_estimate_width",channelMetrics.width, ...
 "channel_rank2_fraction",channelMetrics.rank2_fraction, ...
 "channel_condition_median",channelMetrics.condition_median, ...
 "channel_estimate_rms",channelMetrics.rms, ...
  "requested_packet_transactions",requestedPackets, ...
  "fresh_transaction_fraction",min(completedPackets/requestedPackets,1), ...
  "tx_packet_count",size(tx,1),"rx_packet_count",size(rx,1), ...
 "tx_bit_width",size(tx,2),"rx_bit_width",size(rx,2), ...
 "tx_prefix_summary",localSummary(tx),"rx_prefix_summary",localSummary(rx), ...
 "tx_suffix_summary",localSummary(fliplr(tx)),"rx_suffix_summary",localSummary(fliplr(rx)), ...
 "tx_preview_first",localPreview(tx,32),"rx_preview_first",localPreview(rx,32));
end

function audit=localCandidateStaticAudit(model)
blocks=string(find_system(model,"FollowLinks","on", ...
 "LookUnderMasks","all","Type","Block"));
outputs=["packet_state","synchronization_state","mimo_state","quality_state"];
sinks=strings(size(outputs));connected=false(size(outputs));
for index=1:numel(outputs)
 sinks(index)=localFindVariableSink(blocks,outputs(index));
 connected(index)=localInputConnected(sinks(index));
end
audit=struct( ...
 "mode","candidate_public_behavioral_contract", ...
 "public_output_names",outputs, ...
 "public_output_sinks",sinks, ...
 "public_output_sinks_connected",all(connected), ...
 "public_output_connected",connected, ...
 "official_channel_state_not_exposed",true, ...
 "true_channel_leakage_static_scan_conclusive",false, ...
 "core_path_qualified",all(connected), ...
 "candidate_structure_scan",false);
end

function block=localFindVariableSink(blocks,expected)
block="";
for index=1:numel(blocks)
 try
  if strcmp(strtrim(string(get_param(blocks(index),"VariableName"))),expected)
   block=blocks(index);return;
  end
 catch
 end
end
end

function pass=localInputConnected(block)
pass=false;
if strlength(block)==0,return;end
try
 handles=get_param(block,"PortHandles");
 if isempty(handles.Inport),return;end
 pass=all(arrayfun(@(port)get_param(port,"Line")>0,handles.Inport));
catch
end
end

function localInstallReferenceTaps(model)
rootMap = {
    "TxPSDU", model + "/Transmitter", 1;
    "TxWaveform", model + "/Transmitter", 2;
    "TGnWaveform", model + "/TGn MIMO Channel", 1;
    "AWGNWaveform", model + "/AWGN Channel", 1;
    "RxPSDU", model + "/Receiver", 1;
    "EqualizedSymbols", model + "/Receiver", 2;
    "PERStats", model + "/Calc PER", 1
};
for index = 1:size(rootMap, 1)
    localInstallTap(model, string(rootMap{index, 2}), ...
        double(rootMap{index, 3}), string(rootMap{index, 1}), index);
end

receiver = model + "/Receiver";
receiverMap = {
    "PacketDetected", receiver + "/Packet Detector", 1;
    "CoarsePacketOffset", receiver + "/Packet Detector", 2
};
for index = 1:size(receiverMap, 1)
    localInstallTap(receiver, string(receiverMap{index, 2}), ...
        double(receiverMap{index, 3}), string(receiverMap{index, 1}), index);
end

recovery = receiver + "/Packet Recovery";
recoveryMap = {
    "CoarseCFO", recovery + "/Coarse CFO Estimator", 1;
    "FineCFO", recovery + "/Fine CFO Estimator", 1;
    "TimingOffset", recovery + "/Symbol Timing Estimator", 1;
    "ChannelEstimate", recovery + "/Channel Estimator", 1;
    "NoiseEstimate", recovery + "/Noise Power Estimator", 1
};
for index = 1:size(recoveryMap, 1)
    localInstallTap(recovery, string(recoveryMap{index, 2}), ...
        double(recoveryMap{index, 3}), string(recoveryMap{index, 1}), index);
end
end

function localInstallTap(parent, source, sourcePort, variable, index)
assert(getSimulinkBlockHandle(source) > 0, ...
    "SimuVerity:F90:XCOMM09:ReferenceLocator", ...
    "Missing reference signal source %s.", source);
tap = parent + "/__F90_" + variable;
if getSimulinkBlockHandle(tap) < 0
    add_block("simulink/Sinks/To Workspace", tap, ...
        "VariableName", "F90_" + variable, ...
        "SaveFormat", "Timeseries", ...
        "Save2DSignal", "3-D array (concatenate along third dimension)", ...
        "MaxDataPoints", "inf", ...
        "Position", [1500, 180 + 38 * index, 1660, 205 + 38 * index]);
    sourceHandles = get_param(source, "PortHandles");
    tapHandles = get_param(tap, "PortHandles");
    add_line(parent, sourceHandles.Outport(sourcePort), ...
        tapHandles.Inport(1), "autorouting", "on");
end
end

function localSuppressVisualizationSinks(model)
types = ["ConstellationDiagram", "Display", "Scope"];
for blockType = types
    blocks = find_system(model, "LookUnderMasks", "all", ...
        "FollowLinks", "on", "BlockType", blockType);
    for index = 1:numel(blocks)
        try
            set_param(blocks{index}, "Commented", "on");
        catch
        end
    end
end
end

function localApplyScenario(model, scenario)
parameters = model + "/Model Parameters";
set_param(parameters, ...
    "channelBandwidth", "CBW20", ...
    "numTx", "2", ...
    "numSTS", "2", ...
    "spatialMapping", string(scenario.spatial_mapping), ...
    "numRx", "2", ...
    "mcs", localMcsText(double(scenario.mcs_index)), ...
    "psduLength", "1024");
set_param(model + "/AWGN Channel", ...
    "SNR", string(double(scenario.snr_db)), ...
    "Seed", string(double(scenario.noise_seed)));
set_param(model + "/TGn MIMO Channel", ...
    "DelayProfile", string(scenario.delay_profile), ...
    "Seed", string(double(scenario.channel_seed)));
set_param(model + "/Transmitter/Bernoulli Binary" + newline + "Generator", ...
    "Seed", string(double(scenario.payload_seed)));

values = {
    "mcs_index", double(scenario.mcs_index);
    "snr_db", double(scenario.snr_db);
    "spatial_mapping", string(scenario.spatial_mapping);
    "payload_seed", double(scenario.payload_seed);
    "channel_seed", double(scenario.channel_seed);
    "noise_seed", double(scenario.noise_seed)
};
for index = 1:size(values, 1)
    assignin("base", values{index, 1}, values{index, 2});
end
set_param(model, "StopTime", ...
    string(double(scenario.packet_transactions) - 1));
set_param(model, "SimulationCommand", "update");
end

function value = localMcsText(index)
options = [
    "0 - 1 spatial stream, BPSK-1/2";
    "1 - 1 spatial stream, QPSK-1/2";
    "2 - 1 spatial stream, QPSK-3/4";
    "3 - 1 spatial stream, 16-QAM-1/2";
    "4 - 1 spatial stream, 16-QAM-3/4";
    "5 - 1 spatial stream, 64-QAM-2/3";
    "6 - 1 spatial stream, 64-QAM-3/4";
    "7 - 1 spatial stream, 64-QAM-5/6";
    "8 - 2 spatial streams, BPSK-1/2";
    "9 - 2 spatial streams, QPSK-1/2";
    "10 - 2 spatial streams, QPSK-3/4";
    "11 - 2 spatial streams, 16-QAM-1/2";
    "12 - 2 spatial streams, 16-QAM-3/4";
    "13 - 2 spatial streams, 64-QAM-2/3";
    "14 - 2 spatial streams, 64-QAM-3/4";
    "15 - 2 spatial streams, 64-QAM-5/6"
];
assert(index >= 0 && index <= 15 && index == floor(index), ...
    "SimuVerity:F90:XCOMM09:MCS");
value = options(index + 1);
end

function audit = localStaticAudit(model)
root = struct( ...
    "transmitter_to_tgn", localFeeds(model + "/Transmitter", 2, ...
        model + "/TGn MIMO Channel"), ...
    "tgn_to_awgn", localFeeds(model + "/TGn MIMO Channel", 1, ...
        model + "/AWGN Channel"), ...
    "awgn_to_receiver", localFeeds(model + "/AWGN Channel", 1, ...
        model + "/Receiver"), ...
    "tx_psdu_to_per", localFeeds(model + "/Transmitter", 1, ...
        model + "/Calc PER"), ...
    "rx_psdu_to_per", localFeeds(model + "/Receiver", 1, ...
        model + "/Calc PER"));
receiver = model + "/Receiver";
receiverLinks = struct( ...
    "waveform_to_detector", localFeeds(receiver + "/rxWaveform", 1, ...
        receiver + "/Packet Detector"), ...
    "waveform_to_recovery", localFeeds(receiver + "/rxWaveform", 1, ...
        receiver + "/Packet Recovery"), ...
    "detector_enable_to_recovery", localOutputConnected( ...
        receiver + "/Packet Detector", 1), ...
    "detector_offset_to_recovery", localFeeds( ...
        receiver + "/Packet Detector", 2, receiver + "/Packet Recovery"));
recovery = receiver + "/Packet Recovery";
blocks = [
    recovery + "/Coarse CFO Estimator";
    recovery + "/Coarse CFO" + newline + "Correction";
    recovery + "/Symbol Timing Estimator";
    recovery + "/Fine CFO Estimator";
    recovery + "/Fine CFO " + newline + "Correction";
    recovery + "/Channel Estimator";
    recovery + "/Noise Power Estimator";
    recovery + "/HT-Data Recover"
];
blockPresent = arrayfun(@(path) getSimulinkBlockHandle(path) > 0, blocks);
recoveryLinks = struct( ...
    "coarse_cfo_estimator_connected", localOutputConnected(blocks(1), 1), ...
    "coarse_cfo_correction_connected", localOutputConnected(blocks(2), 1), ...
    "timing_estimator_connected", localOutputConnected(blocks(3), 1), ...
    "fine_cfo_estimator_connected", localOutputConnected(blocks(4), 1), ...
    "fine_cfo_correction_connected", localOutputConnected(blocks(5), 1), ...
    "channel_estimate_to_data_recovery", ...
        localFeeds(blocks(6), 1, blocks(8)), ...
    "noise_estimate_to_data_recovery", ...
        localFeeds(blocks(7), 1, blocks(8)), ...
    "data_recovery_outputs_connected", ...
        localOutputConnected(blocks(8), 1) && ...
        localOutputConnected(blocks(8), 2));
channel = model + "/TGn MIMO Channel";
pathGainsOff = false;
try
    pathGainsOff = string(get_param(channel, "PathGainsOutputPort")) == "off";
catch
end
audit = struct( ...
    "root_causal_links", root, ...
    "receiver_acquisition_links", receiverLinks, ...
    "receiver_mechanism_blocks_present", all(blockPresent), ...
    "recovery_links", recoveryLinks, ...
    "true_channel_path_gains_output_disabled", pathGainsOff, ...
    "true_channel_leak_absent", pathGainsOff);
audit.core_path_qualified = ...
    all(structfun(@logical, root)) && ...
    all(structfun(@logical, receiverLinks)) && ...
    all(blockPresent) && ...
    all(structfun(@logical, recoveryLinks)) && pathGainsOff;
end

function valid = localFeeds(source, sourcePort, target)
valid = false;
try
    handles = get_param(source, "PortHandles");
    line = get_param(handles.Outport(sourcePort), "Line");
    if line < 0, return; end
    destinations = get_param(line, "DstBlockHandle");
    destinations = destinations(destinations > 0);
    valid = any(destinations == getSimulinkBlockHandle(target));
catch
end
end

function valid = localOutputConnected(source, sourcePort)
valid = false;
try
    handles = get_param(source, "PortHandles");
    valid = get_param(handles.Outport(sourcePort), "Line") >= 0;
catch
end
end

function profile = localCompactProfile(model)
profile = struct( ...
    "block_count", numel(find_system(model, "Type", "Block")), ...
    "subsystem_count", numel(find_system(model, ...
        "BlockType", "SubSystem")), ...
    "standard", "IEEE 802.11n HT mixed format", ...
    "antenna_and_stream_contract", "2 Tx, 2 Rx, 2 spatial streams", ...
    "causal_path", [ ...
        "fresh PSDU generation and HT packet construction"; ...
        "two-stream spatial mapping"; ...
        "2-by-2 stochastic TGn multipath fading and AWGN"; ...
        "packet detection and coarse timing"; ...
        "coarse and fine carrier synchronization"; ...
        "HT-LTF-derived 2-by-2 channel estimation"; ...
        "pilot/noise estimation and two-stream equalization"; ...
        "HT data demodulation, decoding and packet comparison"], ...
    "reference_control_target", ...
        "autonomous causal recovery of both spatial streams without true channel leakage");
end

function localClearOutputs
names = ["TxPSDU", "TxWaveform", "TGnWaveform", "AWGNWaveform", ...
    "RxPSDU", "EqualizedSymbols", "PERStats", "PacketDetected", ...
    "CoarsePacketOffset", "CoarseCFO", "FineCFO", "TimingOffset", ...
    "ChannelEstimate", "NoiseEstimate"];
command = "clear";
for name = names
    command = command + " F90_" + name;
end
evalin("base", command);
end

function signals = localReadOutputs(out)
names = ["TxPSDU", "TxWaveform", "TGnWaveform", "AWGNWaveform", ...
    "RxPSDU", "EqualizedSymbols", "PERStats", "PacketDetected", ...
    "CoarsePacketOffset", "CoarseCFO", "FineCFO", "TimingOffset", ...
    "ChannelEstimate", "NoiseEstimate"];
signals = struct();
for index = 1:numel(names)
    name = names(index);
    variable = "F90_" + name;
    value = [];
    try
        value = out.get(variable);
    catch
    end
    if isempty(value)
        try
            value = evalin("base", variable);
        catch
        end
    end
    assert(isa(value, "timeseries"), ...
        "SimuVerity:F90:XCOMM09:MissingTimeseries", ...
        "Required evidence %s is not a Timeseries.", variable);
    [time, matrix, sampleShape] = localFrameMatrix(value);
    signals.(name) = struct( ...
        "time", time, "matrix", matrix, "sample_shape", sampleShape);
end
end

function contract = localOutputContract(signals)
contract = struct( ...
    "tx_psdu_complete", localSignalContract(signals.TxPSDU, 1024, false), ...
    "tx_waveform_two_channel", ...
        localSignalContract(signals.TxWaveform, 2, true), ...
    "tgn_waveform_two_channel", ...
        localSignalContract(signals.TGnWaveform, 2, true), ...
    "awgn_waveform_two_channel", ...
        localSignalContract(signals.AWGNWaveform, 2, true), ...
    "rx_psdu_complete", localSignalContract(signals.RxPSDU, 1024, false), ...
    "equalized_two_stream_complex", ...
        localSignalContract(signals.EqualizedSymbols, 2, true), ...
    "per_three_channels", localSignalContract(signals.PERStats, 3, false), ...
    "packet_detection_nonempty", ...
        localSignalContract(signals.PacketDetected, 1, false), ...
    "coarse_packet_offset_nonempty", ...
        localSignalContract(signals.CoarsePacketOffset, 1, false), ...
    "coarse_cfo_nonempty", localSignalContract(signals.CoarseCFO, 1, false), ...
    "fine_cfo_nonempty", localSignalContract(signals.FineCFO, 1, false), ...
    "timing_offset_nonempty", ...
        localSignalContract(signals.TimingOffset, 1, false), ...
    "channel_estimate_two_by_two", ...
        localSignalContract(signals.ChannelEstimate, 4, true), ...
    "noise_estimate_positive", ...
        localSignalContract(signals.NoiseEstimate, 1, false) && ...
        all(real(signals.NoiseEstimate.matrix) > 0, "all"));
end

function valid = localSignalContract(signal, minimumWidth, requireComplex)
valid = ~isempty(signal.time) && size(signal.matrix, 2) >= minimumWidth && ...
    all(isfinite(real(signal.matrix)), "all") && ...
    all(isfinite(imag(signal.matrix)), "all");
if requireComplex
    valid = valid && any(abs(imag(signal.matrix)) > 1e-12, "all");
end
end

function metrics = localMetrics(signals, scenario)
txBits = round(real(signals.TxPSDU.matrix));
rxBits = round(real(signals.RxPSDU.matrix));
perMatrix = real(signals.PERStats.matrix);
detected = real(signals.PacketDetected.matrix(:)) > 0.5;
coarseOffset = real(signals.CoarsePacketOffset.matrix(:));
coarseCFO = real(signals.CoarseCFO.matrix(:));
fineCFO = real(signals.FineCFO.matrix(:));
timingOffset = real(signals.TimingOffset.matrix(:));
noiseEstimate = real(signals.NoiseEstimate.matrix(:));

perRows = reshape(perMatrix, size(perMatrix, 1), []);
if size(perRows, 2) < 3 && size(perMatrix, 1) == 3
    perRows = perMatrix.';
end
assert(size(perRows, 2) >= 3, "SimuVerity:F90:XCOMM09:PERWidth");
reportedPER = double(perRows(end, 1));
reportedErrors = double(perRows(end, 2));
reportedPackets = double(perRows(end, 3));
perConsistency = abs(reportedPER - ...
    reportedErrors / max(reportedPackets, 1));

rows = min(size(txBits, 1), size(rxBits, 1));
columns = min(size(txBits, 2), size(rxBits, 2));
txCompare = txBits(1:rows, 1:columns);
rxCompare = rxBits(1:rows, 1:columns);
packetError = any(txCompare ~= rxCompare, 2);
manualPER = mean(packetError);

tgn = localChronologicalVector(signals.TGnWaveform.matrix);
awgn = localChronologicalVector(signals.AWGNWaveform.matrix);
count = min(numel(tgn), numel(awgn));
tgn = tgn(1:count);
awgn = awgn(1:count);
noise = awgn - tgn;
measuredSNR = 10 * log10(mean(abs(tgn).^2) / ...
    max(mean(abs(noise).^2), 1e-15));

txWave = localChronologicalVector(signals.TxWaveform.matrix);
count = min(numel(txWave), numel(tgn));
channelDifference = rms(txWave(1:count) - tgn(1:count)) / ...
    max(rms(txWave(1:count)), 1e-12);
channelExactFraction = mean(abs(txWave(1:count) - tgn(1:count)) < 1e-12);

modulationOrder = localModulationOrder(double(scenario.mcs_index));
streams = localStreamMetrics(signals.EqualizedSymbols, modulationOrder);
channel = localChannelMetrics(signals.ChannelEstimate);

metrics = struct( ...
    "reported_per", reportedPER, ...
    "reported_packet_errors", reportedErrors, ...
    "reported_compared_packets", reportedPackets, ...
    "reported_per_consistency_error", perConsistency, ...
    "manual_per", double(manualPER), ...
    "manual_packet_errors", double(sum(packetError)), ...
    "manual_compared_packets", double(rows), ...
    "reported_manual_per_difference", abs(reportedPER - manualPER), ...
    "packet_detection_fraction", double(mean(detected)), ...
    "detected_packet_count", double(sum(detected)), ...
    "coarse_packet_offset_median_samples", double(median(coarseOffset)), ...
    "coarse_packet_offset_span_samples", ...
        double(max(coarseOffset) - min(coarseOffset)), ...
    "coarse_cfo_median_hz", double(median(coarseCFO)), ...
    "coarse_cfo_rms_hz", double(rms(coarseCFO)), ...
    "fine_cfo_median_hz", double(median(fineCFO)), ...
    "fine_cfo_rms_hz", double(rms(fineCFO)), ...
    "symbol_timing_offset_median_samples", double(median(timingOffset)), ...
    "symbol_timing_offset_span_samples", ...
        double(max(timingOffset) - min(timingOffset)), ...
    "noise_estimate_mean", double(mean(noiseEstimate)), ...
    "noise_estimate_median", double(median(noiseEstimate)), ...
    "measured_channel_output_snr_db", double(measuredSNR), ...
    "channel_normalized_difference", double(channelDifference), ...
    "channel_exact_copy_fraction", double(channelExactFraction), ...
    "equalized_stream_count", streams.count, ...
    "stream1_evm", streams.evm1, ...
    "stream2_evm", streams.evm2, ...
    "worst_stream_evm", max(streams.evm1, streams.evm2), ...
    "stream_evm_imbalance", abs(streams.evm1 - streams.evm2), ...
    "equalized_stream_correlation", streams.correlation, ...
    "channel_estimate_width", channel.width, ...
    "channel_rank2_fraction", channel.rank2_fraction, ...
    "channel_condition_median", channel.condition_median, ...
    "channel_estimate_rms", channel.rms, ...
    "tx_packet_count", double(size(txBits, 1)), ...
    "rx_packet_count", double(size(rxBits, 1)), ...
    "tx_bit_width", double(size(txBits, 2)), ...
    "rx_bit_width", double(size(rxBits, 2)), ...
    "tx_prefix_summary", localSummary(txBits), ...
    "rx_prefix_summary", localSummary(rxBits), ...
    "tx_suffix_summary", localSummary(fliplr(txBits)), ...
    "rx_suffix_summary", localSummary(fliplr(rxBits)), ...
    "tx_preview_first", localPreview(txBits, 32), ...
    "rx_preview_first", localPreview(rxBits, 32));
end

function order = localModulationOrder(mcs)
index = mod(mcs, 8);
if index == 0
    order = 2;
elseif index <= 2
    order = 4;
elseif index <= 4
    order = 16;
else
    order = 64;
end
end

function output = localStreamMetrics(signal, modulationOrder)
matrix = signal.matrix;
shape = double(signal.sample_shape);
if ~isempty(shape) && shape(end) == 2
    streamWidth = prod(shape(1:end-1));
else
    streamWidth = floor(size(matrix, 2) / 2);
end
assert(streamWidth > 0 && size(matrix, 2) >= 2 * streamWidth, ...
    "SimuVerity:F90:XCOMM09:EqualizedShape");
stream1 = localChronologicalVector(matrix(:, 1:streamWidth));
stream2 = localChronologicalVector( ...
    matrix(:, streamWidth + 1:2 * streamWidth));
evm1 = localBlindEVM(stream1, modulationOrder);
evm2 = localBlindEVM(stream2, modulationOrder);
count = min(numel(stream1), numel(stream2));
correlation = abs(sum(stream1(1:count) .* conj(stream2(1:count)))) / ...
    max(sqrt(sum(abs(stream1(1:count)).^2) * ...
        sum(abs(stream2(1:count)).^2)), 1e-12);
output = struct( ...
    "count", 2, ...
    "evm1", evm1, ...
    "evm2", evm2, ...
    "correlation", double(correlation));
end

function value = localBlindEVM(values, modulationOrder)
values = values(isfinite(real(values)) & isfinite(imag(values)));
if isempty(values)
    value = Inf;
    return;
end
if numel(values) > 300000
    indices = round(linspace(1, numel(values), 300000));
    values = values(indices);
end
if modulationOrder == 2
    ideal = pskmod((0:1)', 2);
else
    ideal = qammod((0:modulationOrder - 1)', modulationOrder, ...
        "UnitAveragePower", true);
end
normalized = values / sqrt(max(mean(abs(values).^2), 1e-12));
distance = abs(normalized(:) - ideal.');
value = double(sqrt(mean(min(distance, [], 2).^2)));
end

function output = localChannelMetrics(signal)
matrix = signal.matrix;
shape = double(signal.sample_shape);
width = size(matrix, 2);
rankFlags = [];
conditions = [];
if numel(shape) >= 3 && shape(end) == 2 && shape(end - 1) == 2
    toneCount = prod(shape(1:end-2));
    packetIndices = unique(round(linspace(1, size(matrix, 1), ...
        min(size(matrix, 1), 16))));
    toneIndices = unique(round(linspace(1, toneCount, min(toneCount, 32))));
    for packet = packetIndices
        array = reshape(matrix(packet, :), shape);
        array = reshape(array, toneCount, 2, 2);
        for tone = toneIndices
            singular = svd(squeeze(array(tone, :, :)));
            rankFlags(end + 1) = double(singular(2) > ...
                1e-6 * max(singular(1), 1e-12)); %#ok<AGROW>
            conditions(end + 1) = singular(1) / ...
                max(singular(2), 1e-12); %#ok<AGROW>
        end
    end
end
if isempty(rankFlags)
    rankFraction = double(width >= 4 && ...
        any(abs(matrix) > 1e-12, "all"));
    conditionMedian = NaN;
else
    rankFraction = mean(rankFlags);
    conditionMedian = median(conditions);
end
output = struct( ...
    "width", double(width), ...
    "rank2_fraction", double(rankFraction), ...
    "condition_median", double(conditionMedian), ...
    "rms", double(rms(matrix, "all")));
end

function value = localChronologicalVector(matrix)
value = reshape(matrix.', [], 1);
end

function value = localSummary(matrix)
values = reshape(double(real(matrix)).', [], 1);
count = min(numel(values), 8192);
if count == 0
    value = 0;
else
    weights = mod((1:count)', 101) + 1;
    value = double(sum(values(1:count) .* weights));
end
end

function value = localPreview(matrix, count)
values = reshape(double(real(matrix)).', [], 1);
count = min(numel(values), count);
value = values(1:count).';
end

function [time, matrix, sampleShape] = localFrameMatrix(series)
time = double(series.Time(:));
data = series.Data;
dimensions = size(data);
if numel(time) > 1 && dimensions(end) == numel(time)
    order = [ndims(data), 1:ndims(data)-1];
    data = permute(data, order);
    matrix = reshape(data, numel(time), []);
    sampleShape = dimensions(1:end-1);
elseif dimensions(1) == numel(time)
    matrix = reshape(data, numel(time), []);
    sampleShape = dimensions(2:end);
elseif numel(time) == 1
    matrix = reshape(data, 1, []);
    sampleShape = dimensions;
else
    error("SimuVerity:F90:XCOMM09:SignalShape", ...
        "Timeseries data dimensions do not align with time.");
end
matrix = double(matrix);
sampleShape = double(sampleShape);
end

function row = localEmptyScenario
row = struct( ...
    "id", "", ...
    "requested_inputs", struct(), ...
    "simulation_pass", false, ...
    "valid", false, ...
    "output_contract", struct(), ...
    "metrics", struct(), ...
    "wall_seconds", 0, ...
    "error", struct());
end

function localConfigureFileGeneration
cache = string(getenv("SIMULINK_CACHE_FOLDER"));
codegen = string(getenv("SIMULINK_CODEGEN_FOLDER"));
if strlength(cache) > 0 && strlength(codegen) > 0
    if ~isfolder(cache), mkdir(cache); end
    if ~isfolder(codegen), mkdir(codegen); end
    Simulink.fileGenControl("set", "CacheFolder", cache, ...
        "CodeGenFolder", codegen, "createDir", true);
end
end

function root = localProjectRoot
root = fileparts(mfilename("fullpath"));
for level = 1:4
    root = fileparts(root);
end
end

function value = localFilePresence(path)
assert(isfile(path), "SimuVerity:FileMissing", "Required file is missing: %s", path);
value = "present";
end

function value = localNow
value = string(datetime("now", "TimeZone", "Asia/Shanghai", ...
    "Format", "yyyy-MM-dd'T'HH:mm:ssXXX"));
end

function output = localError(exception)
output = struct( ...
    "identifier", string(exception.identifier), ...
    "message", string(exception.message), ...
    "report", string(getReport(exception, "extended", ...
        "hyperlinks", "off")));
end

function localWriteJson(path, value)
fid = fopen(path, "w", "n", "UTF-8");
assert(fid >= 0, "SimuVerity:F90:XCOMM09:Write");
cleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
fprintf(fid, "%s\n", jsonencode(value, PrettyPrint=true));
end
